function surahOf(n) {
	return SURAHS[n - 1] ?? SURAHS[0];
}
function refToGlobal(surah, ayah) {
	return (START[surah] ?? 1) + ayah - 1;
}
function globalToRef(g) {
	let n = 1;
	for (const s of SURAHS) {
		const start = START[s.n];
		if (g < start + s.ayahs) return {
			surah: s.n,
			ayah: g - start + 1
		};
		n = s.n;
	}
	return {
		surah: n,
		ayah: 1
	};
}
var cache = null;
var pending = null;
function loadMushaf() {
	if (cache) return Promise.resolve(cache);
	if (!pending) pending = fetch("/quran/mushaf.json").then((r) => {
		if (!r.ok) throw new Error("mushaf");
		return r.json();
	}).then((data) => {
		cache = data;
		return data;
	}).catch((err) => {
		pending = null;
		throw err;
	});
	return pending;
}
async function loadSurah(n) {
	const all = await loadMushaf();
	return all[n - 1] ?? all[0];
}
async function loadAyah(surah, ayah) {
	return (await loadSurah(surah)).ayahs.find((a) => a.i === ayah) ?? null;
}
function dayAyahRef(date = /* @__PURE__ */ new Date()) {
	const start = Date.UTC(date.getFullYear(), 0, 0);
	return globalToRef((Math.floor((date.getTime() - start) / 864e5) - 1) % 6236 + 1);
}
function searchMushaf(all, q, limit = 40) {
	const needle = q.trim().toLowerCase();
	if (needle.length < 2) return [];
	const out = [];
	for (const s of all) for (const a of s.ayahs) if (a.ru.toLowerCase().includes(needle) || a.ar.includes(q.trim())) {
		out.push({
			surah: s.n,
			ayah: a
		});
		if (out.length >= limit) return out;
	}
	return out;
}
function formatRef(surah, ayah) {
	return `${surahOf(surah).ru} ${surah}:${ayah}`;
}
